// ==UserScript==
// @name         KISSU · Recordatorio Cupo (pegar lista → recordatorio1 + imagen)
// @namespace    http://tampermonkey.net/
// @version      1.1.2
// @description  Pega la lista (cédula, nombre, celular, cupo), y por cada persona crea el contacto en WhaTicket y envía la plantilla "recordatorio1" (nombre, cupo, cédula) CON IMAGEN por la línea Kissu. Con estimado de tiempo, contador en vivo, pausas, tope por tanda y control de duplicados.
// @author       KISSU
// @updateURL    https://raw.githubusercontent.com/ContenidoKissu/kissu-scripts/main/recordatorio-cupo.user.js
// @downloadURL  https://raw.githubusercontent.com/ContenidoKissu/kissu-scripts/main/recordatorio-cupo.user.js
// @match        https://app.whaticket.com/*
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_addValueChangeListener
// @grant        GM_addStyle
// @grant        unsafeWindow
// @run-at       document-idle
// @noframes
// ==/UserScript==

(function () {
  'use strict';

  // ═══════════════════════════════════════════════════════════════════════════
  // CONFIGURACIÓN
  // ═══════════════════════════════════════════════════════════════════════════
  const CFG = {
    // Línea de WhatsApp por la que SIEMPRE se debe enviar.
    CONEXION_NOMBRE: 'Kissu',
    CONEXION_NUMERO: '593993310556',
    // Usar el nombre real del cliente al crear el contacto (si no, queda el número)
    NOMBRE_CONTACTO_REAL: true,

    // Plantilla de Meta a enviar y cuántas variables tiene.
    PLANTILLA: 'recordatorio1',
    N_VARS: 3,               // {{1}} nombre · {{2}} cupo · {{3}} cédula

    // Imagen obligatoria: se adjunta en "Adjuntar medio" de la plantilla.
    // Si la plantilla no muestra ese campo, NO se envía (para no mandarla sin imagen).
    CON_IMAGEN: true,

    // Seguridad: true = NO envía nada, solo simula y muestra las variables.
    SIMULACION: true,

    // Pausa (segundos) entre un cliente y el siguiente. Aleatoria entre min y max.
    PAUSA_MIN: 4,
    PAUSA_MAX: 7,

    // Tope de envíos por corrida (para hacerlo en tandas).
    MAX_POR_TANDA: 60,

    // Overhead aproximado de la UI por contacto (para el estimado PREVIO;
    // el contador en vivo se corrige solo con el tiempo real).
    SEG_UI_APROX: 22,
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // UTILIDADES
  // ═══════════════════════════════════════════════════════════════════════════
  const PANEL_ID = '#kr-panel';
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const WIN = (typeof unsafeWindow !== 'undefined' && unsafeWindow) || document.defaultView || window;
  let detener = false;

  function log(msg, tipo = 'info') {
    const box = document.getElementById('kr-log');
    console.log(`[KISSU-REC] ${msg}`);
    if (!box) return;
    const el = document.createElement('div');
    el.className = tipo;
    el.textContent = `${new Date().toLocaleTimeString()}  ${msg}`;
    box.appendChild(el);
    box.scrollTop = box.scrollHeight;
    while (box.children.length > 250) box.removeChild(box.firstChild);
  }

  function realClick(el) {
    if (!el) return;
    const r = el.getBoundingClientRect();
    const o = { bubbles: true, cancelable: true, view: WIN,
                clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 };
    try { el.dispatchEvent(new PointerEvent('pointerdown', o)); } catch (_) {}
    el.dispatchEvent(new MouseEvent('mousedown', o));
    try { el.dispatchEvent(new PointerEvent('pointerup', o)); } catch (_) {}
    el.dispatchEvent(new MouseEvent('mouseup', o));
    el.dispatchEvent(new MouseEvent('click', o));
    try { el.click(); } catch (_) {}
  }

  // Clic ÚNICO (sin el.click() extra). Se usa en "Agregar archivo" para que
  // el selector de archivos no se dispare dos veces.
  function clickUnico(el) {
    if (!el) return;
    const r = el.getBoundingClientRect();
    const o = { bubbles: true, cancelable: true, view: WIN,
                clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 };
    el.dispatchEvent(new MouseEvent('mousedown', o));
    el.dispatchEvent(new MouseEvent('mouseup', o));
    el.dispatchEvent(new MouseEvent('click', o));
  }

  function setVal(el, valor) {
    const proto = el.tagName === 'TEXTAREA'
      ? WIN.HTMLTextAreaElement.prototype : WIN.HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    if (setter) setter.call(el, valor); else el.value = valor;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }

  const textoDe = el => (el?.innerText || el?.textContent || '').trim();

  function buscarPorTexto(sel, test, filtro) {
    for (const el of document.querySelectorAll(sel)) {
      if (el.closest(PANEL_ID)) continue;
      if (test(textoDe(el)) && (!filtro || filtro(el))) return el;
    }
    return null;
  }

  // Nombre → primer nombre en formato "Ismael"
  function primerNombre(n) {
    const t = String(n || '').trim().split(/\s+/)[0] || '';
    return t ? t.charAt(0).toUpperCase() + t.slice(1).toLowerCase() : '';
  }

  // Celular → 593 + número sin el 0 inicial. 0984636885 → 593984636885
  function telE164(cel) {
    let d = String(cel == null ? '' : cel).replace(/\D/g, '');
    if (!d) return '';
    if (d.startsWith('593')) return d;
    if (d.startsWith('0')) d = d.slice(1);
    return '593' + d;
  }

  function fmtDur(seg) {
    seg = Math.max(0, Math.round(seg));
    const h = Math.floor(seg / 3600), m = Math.floor((seg % 3600) / 60), s = seg % 60;
    if (h) return `${h} h ${m} min`;
    if (m) return `${m} min ${s} s`;
    return `${s} s`;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // COLA (persistida en Tampermonkey)
  // item = { cedula, nombre, telefono, cupo, estado, motivo, ts }
  // estado: 'pendiente' | 'enviado' | 'simulado' | 'error'
  // ═══════════════════════════════════════════════════════════════════════════
  const K_COLA = 'kissu_rec_cola_v1';
  const K_SIM = 'kissu_rec_sim';
  const K_P1 = 'kissu_rec_pausa_min';
  const K_P2 = 'kissu_rec_pausa_max';
  const K_TOPE = 'kissu_rec_tope';
  const K_TMPL = 'kissu_rec_tmpl';

  const getCola = () => { try { return JSON.parse(GM_getValue(K_COLA, '[]')); } catch { return []; } };
  const setCola = c => GM_setValue(K_COLA, JSON.stringify(c));
  function actualizar(cedula, cambios) {
    const c = getCola(); const i = c.findIndex(x => x.cedula === cedula);
    if (i >= 0) { Object.assign(c[i], cambios); setCola(c); }
  }

  // ── Parseo de lo pegado ──────────────────────────────────────────────────
  function parseLinea(line) {
    const raw = line.trim(); if (!raw) return null;
    const bajo = raw.toLowerCase();
    if ((/c[eé]dula/.test(bajo)) && /nombre/.test(bajo)) return null; // encabezado
    let cols;
    if (raw.includes('\t')) {
      cols = raw.split('\t').map(s => s.trim());
    } else {
      // sin tabulaciones: cédula al inicio, cupo = token con $ o decimal .00/,00
      const t = raw.split(/\s+/);
      let iC = -1;
      for (let i = 1; i < t.length; i++) {
        if (/\$/.test(t[i]) || /^\d{1,3}([.,]\d{3})*[.,]\d{2}$/.test(t[i]) || /^\d+[.,]\d{2}$/.test(t[i])) { iC = i; break; }
      }
      if (iC < 2) return null;
      cols = [t[0], t.slice(1, iC - 1).join(' '), t[iC - 1], t[iC]];
    }
    if (cols.length < 4) return null;
    const cedula = String(cols[0]).replace(/\D/g, '');
    if (!/^\d{6,}$/.test(cedula)) return null;
    return { cedula, nombre: cols[1] || '', celular: cols[2] || '', cupo: (cols[3] || '').trim() };
  }

  function cargarLista(txt) {
    const nuevos = [], seen = new Set();
    txt.split(/\r?\n/).forEach(l => {
      const p = parseLinea(l); if (!p) return;
      if (seen.has(p.cedula)) return; seen.add(p.cedula);
      nuevos.push({ cedula: p.cedula, nombre: p.nombre, telefono: telE164(p.celular),
                    cupo: p.cupo, estado: 'pendiente', motivo: '', ts: 0 });
    });
    // fusionar con la cola existente sin borrar estados ya enviados
    const prev = getCola();
    const map = new Map(prev.map(x => [x.cedula, x]));
    let add = 0, dup = 0;
    nuevos.forEach(n => {
      if (map.has(n.cedula)) { dup++; } else { map.set(n.cedula, n); add++; }
    });
    setCola([...map.values()]);
    return { add, dup, total: map.size };
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // FLUJO WHATICKET — reutilizado del script probado (solo UI, sin API interna)
  // ═══════════════════════════════════════════════════════════════════════════
  const SEL_DLG = '[role="dialog"], [class*="Dialog"], [class*="dialog"], [class*="Modal"], [class*="modal"]';

  function dialogoCon(txt) {
    let mejor = null;
    for (const d of document.querySelectorAll(SEL_DLG)) {
      if (d.closest(PANEL_ID) || d.offsetHeight < 150) continue;
      if (!(d.innerText || '').includes(txt)) continue;
      const area = d.offsetHeight * d.offsetWidth;
      if (!mejor || area < mejor.offsetHeight * mejor.offsetWidth) mejor = d;
    }
    return mejor;
  }
  async function esperarDialogo(txt, ms = 8000) {
    for (let i = 0; i < ms / 200; i++) {
      const d = dialogoCon(txt);
      if (d) { await sleep(400); return d; }
      await sleep(200);
    }
    return null;
  }
  async function abrirIniciarChat() {
    if (dialogoCon('Iniciar un chat')) return dialogoCon('Iniciar un chat');
    const vh = window.innerHeight, vw = window.innerWidth;
    const btns = [...document.querySelectorAll('button, [role="button"], a')].filter(b => !b.closest(PANEL_ID));
    // 1) por etiqueta/título/aria-label
    const porEtiqueta = btns.filter(b => {
      const s = ((b.getAttribute('aria-label') || '') + ' ' + (b.getAttribute('title') || '') + ' ' + textoDe(b)).toLowerCase();
      return /nuevo chat|iniciar( un)? chat|nueva conversa|new chat/.test(s);
    });
    // 2) botón flotante "+" abajo a la izquierda de la lista de chats
    const enZonaFAB = btns.filter(b => {
      const r = b.getBoundingClientRect();
      return r.width > 0 && r.height > 0 && r.left < Math.min(vw * 0.55, 520) && r.top > vh - 210 &&
             r.width > 24 && r.width < 120 && r.height > 24 && r.height < 120;
    }).sort((a, b) => b.getBoundingClientRect().top - a.getBoundingClientRect().top);
    const cand = [...new Set([...porEtiqueta, ...enZonaFAB])];
    for (const b of cand.slice(0, 6)) {
      realClick(b);
      const d = await esperarDialogo('Iniciar un chat', 2500);
      if (d) return d;
    }
    log('❌ No encontré el botón + para iniciar un chat. Ábrelo tú una vez y vuelvo a intentar.', 'error');
    return null;
  }
  async function buscarContacto(modal, num) {
    const inp = [...modal.querySelectorAll('input')].find(i => {
      const ph = (i.placeholder || '').toLowerCase();
      return ph.includes('nombre') || ph.includes('número') || ph.includes('numero') || ph.includes('buscar');
    }) || [...modal.querySelectorAll('input')].pop();
    if (!inp) return null;
    inp.focus(); setVal(inp, ''); await sleep(400);
    setVal(inp, num); await sleep(2000);
    return inp;
  }
  function filaContacto(modal, num) {
    const filas = [...modal.querySelectorAll('li, div')].filter(e => {
      const t = textoDe(e);
      if (!t.includes(num) || /a[ñn]adir/i.test(t)) return false;
      return e.offsetHeight > 28 && e.offsetHeight < 100 && e.offsetWidth > 150;
    });
    return filas.find(f => !filas.some(o => o !== f && f.contains(o))) || filas[0] || null;
  }
  function botonIniciar(modal) {
    return [...modal.querySelectorAll('button')].find(b => /iniciar conversaci/i.test(textoDe(b)));
  }
  function opcionAnadir(modal, num) {
    return [...modal.querySelectorAll('div, span, button, a, li')]
      .find(e => /a[ñn]adir/i.test(textoDe(e)) && textoDe(e).replace(/\D/g, '').includes(num)
                 && e.offsetHeight > 15 && e.offsetHeight < 80);
  }
  async function esperarResultadoContacto(modal, num, ms = 7000) {
    for (let i = 0; i < ms / 250; i++) {
      const fila = filaContacto(modal, num); if (fila) return { fila };
      const anadir = opcionAnadir(modal, num); if (anadir) return { anadir };
      await sleep(250);
    }
    return {};
  }

  // Selecciona la línea Kissu. NUNCA toca "Departamento". Si no puede aislarla,
  // no bloquea: sigue con la línea por defecto (que suele ser Kissu).
  async function seleccionarConexion(modal) {
    const objetivo = (CFG.CONEXION_NUMERO || '').replace(/\D/g, '');
    const nombre = (CFG.CONEXION_NOMBRE || '').toLowerCase();
    if (!objetivo && !nombre) return true;
    const coincide = txt => { const t = (txt || ''); const n = t.replace(/\D/g, '');
      return (objetivo && n.includes(objetivo)) || (nombre && t.toLowerCase().includes(nombre)); };
    const esLabelConexion = txt => /^conexi[oó]n\s*\*?\s*$/i.test((txt || '').trim());
    const mencionaDepartamento = el => /departament/i.test(textoDe(el));
    const raiz = (modal && modal.isConnected) ? modal : document;

    let campo = null;
    for (const f of raiz.querySelectorAll('mat-form-field, .mat-form-field, .mat-mdc-form-field')) {
      if (f.closest(PANEL_ID)) continue;
      const lbl = textoDe(f.querySelector('mat-label, label, .mat-label, .mdc-floating-label, .mat-form-field-label'));
      if (esLabelConexion(lbl)) { campo = f; break; }
    }
    if (!campo) {
      for (const el of raiz.querySelectorAll('label, span, div, p, mat-label')) {
        if (el.closest(PANEL_ID)) continue;
        if (!esLabelConexion(textoDe(el))) continue;
        let cont = el;
        for (let i = 0; i < 4 && cont; i++) {
          const tieneSelect = cont.querySelector('mat-select, [role="combobox"], [class*="mat-select"], select, input');
          if (tieneSelect && !mencionaDepartamento(cont)) { campo = cont; break; }
          cont = cont.parentElement;
        }
        if (campo) break;
      }
    }
    if (campo && mencionaDepartamento(campo)) {
      let interno = null;
      for (const f of campo.querySelectorAll('mat-form-field, .mat-form-field, .mat-mdc-form-field')) {
        const lbl = textoDe(f.querySelector('mat-label, label, .mat-label, .mdc-floating-label, .mat-form-field-label'));
        if (esLabelConexion(lbl) && !mencionaDepartamento(f)) { interno = f; break; }
      }
      campo = interno;
    }
    if (!campo) {
      if (coincide(textoDe(raiz))) log(`🔌 Conexión ya parece ser ${CFG.CONEXION_NOMBRE} (por defecto)`, 'info');
      else log('⚠ No aislé el campo "Conexión" sin riesgo; sigo con la línea por defecto', 'warn');
      return true;
    }
    const control = campo.querySelector('mat-select, [role="combobox"], [class*="mat-select"], select, input') || campo;
    const valActual = (control.value || textoDe(control) || textoDe(campo) || '');
    if (coincide(valActual)) { log(`🔌 Conexión ya es ${CFG.CONEXION_NOMBRE}`, 'info'); return true; }
    for (let intento = 0; intento < 3; intento++) {
      realClick(control); await sleep(700);
      const opciones = [...document.querySelectorAll('mat-option, [role="option"], .mat-option, .mat-mdc-option, li')]
        .filter(o => !o.closest(PANEL_ID) && o.offsetParent !== null);
      const op = opciones.find(o => coincide(textoDe(o)));
      if (op) {
        realClick(op); await sleep(600);
        const v2 = (control.value || textoDe(control) || textoDe(campo) || '');
        if (coincide(v2)) { log(`🔌 Conexión fijada en ${CFG.CONEXION_NOMBRE}`, 'success'); return true; }
      } else if (intento === 0 && opciones.length) { realClick(control); await sleep(300); }
    }
    log(`⚠ No pude cambiar la conexión a ${CFG.CONEXION_NOMBRE}; sigo con la actual`, 'warn');
    return true;
  }

  // ── Buscar el número en el BUSCADOR DE LA LISTA y abrir el chat si existe ──
  // Barra de la columna del medio: "Nombre, número o email".
  // Se descarta a propósito el "Buscar" global de la izquierda y los campos de modales.
  function inputBusquedaLista() {
    const ins = [...document.querySelectorAll('input, textarea')]
      .filter(i => !i.closest(PANEL_ID) && !i.closest(SEL_DLG))
      .filter(i => { const r = i.getBoundingClientRect(); return r.width > 120 && r.height > 0 && r.top < window.innerHeight * 0.45; });
    // 1) placeholder exacto "Nombre, número o email"
    const exacto = ins.find(i => /nombre.*(número|numero).*(email|mail|correo)/i.test(i.placeholder || ''));
    if (exacto) return exacto;
    // 2) cualquiera con email/correo en la columna central (left>240 evita el "Buscar" global)
    const byMail = ins.find(i => /(email|mail|correo)/i.test(i.placeholder || '') && i.getBoundingClientRect().left > 240);
    if (byMail) return byMail;
    // 3) placeholder con número, en la columna central
    const byNum = ins.find(i => /(número|numero)/i.test(i.placeholder || '') && i.getBoundingClientRect().left > 240);
    if (byNum) return byNum;
    // 4) último recurso: primer input central que NO sea el "Buscar" global
    const noGlobal = ins.filter(i => !/^buscar$/i.test((i.placeholder || '').trim()) && i.getBoundingClientRect().left > 240);
    return noGlobal[0] || null;
  }

  // Primera fila de chat que apareció bajo el buscador (misma columna de la lista)
  function filaChatResultado() {
    const s = inputBusquedaLista(); if (!s) return null;
    const rs = s.getBoundingClientRect();
    const cand = [...document.querySelectorAll('div, li, a')].filter(e => {
      if (e.closest(PANEL_ID) || e.closest(SEL_DLG)) return false;
      const r = e.getBoundingClientRect();
      if (r.top < rs.bottom + 30) return false;             // debajo del buscador y de las pestañas
      if (r.left < rs.left - 30 || r.left > rs.left + 70) return false; // misma columna
      if (r.width < 170 || r.width > 640) return false;     // ancho de fila de chat
      if (r.height < 40 || r.height > 140) return false;    // alto de una fila
      const t = textoDe(e);
      if (!t || t.length < 2) return false;
      if (/en atención|en espera|aplazado|no leídos|^equipo$|^interno$/i.test(t)) return false; // pestañas
      return true;
    });
    const filas = cand.filter(f => !cand.some(o => o !== f && f.contains(o)));
    filas.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
    return filas[0] || null;
  }

  async function abrirChatExistente(item) {
    const num = (item.telefono || '').replace(/\D/g, '');
    if (!num) return false;
    const s = inputBusquedaLista();
    if (!s) { log('⚠ No ubiqué el buscador de la lista; voy directo a crear', 'warn'); return false; }
    log(`🔍 Buscando ${num} en la lista…`, 'info');
    s.focus(); setVal(s, ''); await sleep(500);
    setVal(s, num); await sleep(2300);
    const fila = filaChatResultado();
    if (!fila) { log(`🔍 ${num}: sin chat previo → se creará`, 'info'); setVal(s, ''); await sleep(300); return false; }
    realClick(fila); await sleep(1600);
    log('📂 Chat existente abierto', 'success');
    return true;
  }

  // Textos de avisos/toasts visibles en la página (errores de WhaTicket)
  function leerAvisos() {
    const sel = 'mat-snack-bar-container, .mat-mdc-snack-bar-container, simple-snack-bar, [role="alert"], ' +
                '.toast, .Toastify__toast, .swal2-popup, .notification, .alert';
    return [...document.querySelectorAll(sel)]
      .filter(e => !e.closest(PANEL_ID) && e.offsetParent !== null)
      .map(e => textoDe(e).replace(/\s+/g, ' ').trim())
      .filter(t => t.length > 2);
  }

  async function crearChat(item) {
    const num = (item.telefono || '').replace(/\D/g, '');
    if (!num) return false;
    log(`➕ Abriendo chat para ${num}…`, 'info');
    let modal = await abrirIniciarChat();
    if (!modal) return false;

    await buscarContacto(modal, num);
    let { fila, anadir } = await esperarResultadoContacto(modal, num);
    if (!fila && !anadir) { log(`❌ No apareció ni contacto ni "Añadir" para ${num}`, 'error'); return false; }

    if (!fila) {
      realClick(anadir);
      const alta = await esperarDialogo('Agregar contacto');
      if (!alta) { log('❌ No se abrió "Agregar contacto"', 'error'); return false; }
      if (CFG.NOMBRE_CONTACTO_REAL && item.nombre) {
        const nom = [...alta.querySelectorAll('input')].find(i => {
          const r = i.getBoundingClientRect();
          return r.width > 100 && i.type !== 'tel' && !/@/.test(i.value || '');
        });
        if (nom) { setVal(nom, item.nombre); await sleep(300); }
      }
      const guardar = [...alta.querySelectorAll('button')].find(b => /^agregar$/i.test(textoDe(b)) && !b.disabled);
      if (!guardar) { log('❌ Botón "Agregar" no disponible', 'error'); return false; }
      realClick(guardar); await sleep(2500);

      modal = dialogoCon('Iniciar un chat');
      for (let i = 0; i < 16 && !modal; i++) { await sleep(400); modal = dialogoCon('Iniciar un chat'); }
      if (!modal && !dialogoCon('Agregar contacto')) {
        modal = await abrirIniciarChat();
        if (modal) await buscarContacto(modal, num);
      }
      if (!modal) { log('❌ Se perdió el modal tras agregar el contacto', 'error'); return false; }
      ({ fila } = await esperarResultadoContacto(modal, num, 4000));
      if (!fila) { await buscarContacto(modal, num); ({ fila } = await esperarResultadoContacto(modal, num, 4000)); }
      log(`👤 Contacto ${item.nombre || num} registrado`, 'success');
    }

    if (fila) { realClick(fila); await sleep(900); }
    await seleccionarConexion(modal);
    modal = dialogoCon('Iniciar un chat') || modal;

    let btn = null;
    for (let i = 0; i < 24; i++) {
      modal = dialogoCon('Iniciar un chat') || modal;
      btn = botonIniciar(modal);
      if (btn && !btn.disabled && btn.getAttribute('aria-disabled') !== 'true') break;
      await sleep(300);
    }
    if (!btn || btn.disabled) { log('❌ "Iniciar conversación" sigue deshabilitado', 'error'); return false; }

    const antes = location.pathname;
    const avisosAntes = new Set(leerAvisos());
    btn.click();
    for (let i = 0; i < 30; i++) {
      await sleep(300);
      if (location.pathname !== antes || !dialogoCon('Iniciar un chat')) {
        log('✅ Conversación abierta', 'success'); await sleep(1600); return true;
      }
      // ¿WhaTicket mostró un aviso/error? (p. ej. ticket abierto con otro usuario)
      const nuevos = leerAvisos().filter(t => !avisosAntes.has(t));
      if (nuevos.length) {
        log(`⚠ WhaTicket dice: "${nuevos.join(' | ').slice(0, 220)}"`, 'warn');
        break;
      }
      if (i === 5) { const b2 = botonIniciar(dialogoCon('Iniciar un chat') || modal); if (b2) realClick(b2); }
    }
    log('⚠ "Iniciar conversación" no respondió', 'warn');
    // Diagnóstico: qué muestra el modal (conexión, contacto elegido, etc.)
    const m = dialogoCon('Iniciar un chat');
    if (m) log(`🔎 Modal: ${textoDe(m).replace(/\s+/g, ' ').slice(0, 220)}`, 'info');
    return false;
  }

  // ── Plantilla ──────────────────────────────────────────────────────────────
  function modalPlantilla() {
    for (const d of document.querySelectorAll(SEL_DLG)) {
      if (d.closest(PANEL_ID)) continue;
      const t = d.innerText || '';
      if (/plantilla/i.test(t) && /variable/i.test(t)) return d;
    }
    return null;
  }
  async function abrirModalPlantilla() {
    if (modalPlantilla()) return true;
    // WhaTicket ahora muestra el botón como "Plantilla" (antes "Plantilla de mensaje")
    const esBtnPlantilla = t => t.length < 40 && /(^|\s)plantilla( de mensaje)?$/i.test(t);
    const abajo = el => { const r = el.getBoundingClientRect(); return r.bottom > window.innerHeight * 0.5 && r.width > 20; };
    let btn = buscarPorTexto('button, [role="button"]', esBtnPlantilla, abajo);
    if (!btn) {
      const el = buscarPorTexto('div, span, a', esBtnPlantilla, abajo);
      if (el) btn = el.querySelector('button, [role="button"]') || el.closest('button, [role="button"]') || el;
    }
    if (!btn) { log('❌ No encontré el botón "Plantilla"', 'error'); return false; }
    realClick(btn);
    for (let i = 0; i < 14; i++) { await sleep(300); if (modalPlantilla()) return true; }
    log('❌ El modal de plantilla no apareció', 'error');
    return false;
  }
  async function elegirPlantilla(nombre) {
    const modal = modalPlantilla(); if (!modal) return false;
    const combo = modal.querySelector('input, [role="combobox"], [class*="select"], [class*="Select"]');
    if (combo) { realClick(combo); await sleep(700); }
    const busq = modal.querySelector('input[placeholder*="uscar"]')
      || document.querySelector('input[placeholder*="uscar"]') || modal.querySelector('input[type="text"]');
    if (busq) { busq.focus(); setVal(busq, ''); await sleep(300); setVal(busq, nombre); await sleep(1600); }
    const rBusq = busq ? busq.getBoundingClientRect() : null;
    const coincide = t => t === nombre.toLowerCase() || t.startsWith(nombre.toLowerCase());
    const vistas = new Set();
    for (let intento = 0; intento < 4; intento++) {
      let opt = null;
      for (const el of document.querySelectorAll('span, li, div, p, [role="option"]')) {
        if (el.closest(PANEL_ID) || el.tagName === 'INPUT') continue;
        const t = textoDe(el).toLowerCase();
        if (!t || t.length > 60) continue;
        const r = el.getBoundingClientRect();
        if (!r.width || !r.height) continue;
        if (rBusq && r.top <= rBusq.bottom - 2) continue;
        if (el.children.length === 0) vistas.add(t);
        if (!coincide(t)) continue;
        opt = el; break;
      }
      if (opt) {
        let destino = opt, anc = opt.parentElement;
        for (let i = 0; i < 2 && anc; i++) { if (coincide(textoDe(anc).toLowerCase())) destino = anc; anc = anc.parentElement; }
        realClick(destino); await sleep(900);
        const m = modalPlantilla();
        if (m && /variable\s*\{\{\s*1/i.test(m.innerText)) return true;
      }
      await sleep(700);
    }
    if (busq) {
      busq.focus();
      const k = { bubbles: true, cancelable: true, view: WIN };
      busq.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', keyCode: 40, ...k }));
      await sleep(400);
      busq.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, ...k }));
      await sleep(900);
      const m = modalPlantilla();
      if (m && /variable\s*\{\{\s*1/i.test(m.innerText)) return true;
    }
    log(`⚠ No pude seleccionar la plantilla "${nombre}". Visibles: ${[...vistas].slice(0, 8).join(' | ') || '(ninguna)'}`, 'error');
    return false;
  }
  function inputsPlantilla(modal, nVars) {
    const mapa = {}, etiquetas = [];
    for (const el of modal.querySelectorAll('label, span, div, p')) {
      const m = textoDe(el).match(/^Variable\s*\{\{\s*(\d)\s*\}\}\s*\*?$/i);
      if (m) etiquetas.push({ n: +m[1], el });
    }
    for (const { n, el } of etiquetas) {
      if (mapa[n]) continue;
      const rl = el.getBoundingClientRect();
      let mejor = null, dist = Infinity;
      for (const inp of modal.querySelectorAll('input')) {
        if (inp.closest(PANEL_ID)) continue;
        if (!['text', '', 'search', 'tel'].includes((inp.type || 'text').toLowerCase())) continue;
        const d = inp.getBoundingClientRect().top - rl.bottom;
        if (d >= -5 && d < dist) { dist = d; mejor = inp; }
      }
      if (mejor) mapa[n] = mejor;
    }
    if (Object.keys(mapa).length < nVars) {
      const libres = [...modal.querySelectorAll('input')]
        .filter(i => !i.closest(PANEL_ID))
        .filter(i => ['text', '', 'search', 'tel'].includes((i.type || 'text').toLowerCase()))
        .filter(i => !/plantilla|seleccione|buscar/i.test(i.placeholder || ''))
        .sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
      libres.slice(0, nVars).forEach((inp, i) => { if (!mapa[i + 1]) mapa[i + 1] = inp; });
    }
    return mapa;
  }
  // Cierra el modal de plantilla sin enviar (para el modo ensayo)
  function cerrarModalPlantilla(modal) {
    const cont = (modal && (modal.parentElement || modal)) || document;
    const cancelar = [...cont.querySelectorAll('button, [role="button"]')]
      .find(b => !b.closest(PANEL_ID) && /^(cancelar|cerrar)$/i.test(textoDe(b)));
    if (cancelar) { realClick(cancelar); return; }
    const x = [...cont.querySelectorAll('button, [role="button"], [aria-label]')]
      .find(b => !b.closest(PANEL_ID) && (/^[×✕✖xX]$/.test(textoDe(b)) || /close|cerrar/i.test(b.getAttribute('aria-label') || '')));
    if (x) { realClick(x); return; }
    document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true, view: WIN }));
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // IMAGEN QUE ACOMPAÑA A LA PLANTILLA (mismo método que Cupo Aprobado)
  // Va embebida en alta calidad (PNG original 1600×800, sin recomprimir).
  // Se puede cambiar desde el panel; "Original" vuelve a esta.
  // ═══════════════════════════════════════════════════════════════════════════
  const K_IMG = 'kissu_rec_img';
  const K_IMG_NOMBRE = 'kissu_rec_img_nombre';
  const IMG_DEF_NOMBRE = 'FORTALECE_TU_BURO_KISSU.png';
  const IMG_DEF = 'data:image/png;base64,';

  function imagenActual() { return GM_getValue(K_IMG, '') || IMG_DEF; }
  function nombreImagen() { return GM_getValue(K_IMG, '') ? GM_getValue(K_IMG_NOMBRE, 'imagen') : IMG_DEF_NOMBRE; }

  function archivoImagen() {
    const url = imagenActual();
    const [cab, b64] = url.split(',');
    const mime = (cab.match(/data:([^;]+)/) || [])[1] || 'image/png';
    const bin = atob(b64);
    const u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    let nombre = nombreImagen();
    if (!/\.\w{3,4}$/.test(nombre)) nombre += '.' + (mime.split('/')[1] || 'png').replace('jpeg', 'jpg');
    const F = WIN.File || File;
    return new F([u8], nombre, { type: mime, lastModified: Date.now() });
  }

  function meterArchivo(input, file) {
    const DT = WIN.DataTransfer || DataTransfer;
    const dt = new DT();
    dt.items.add(file);
    try { input.files = dt.files; } catch (_) {
      Object.defineProperty(input, 'files', { value: dt.files, configurable: true });
    }
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }

  // ¿La plantilla elegida pide imagen? (campo "Adjuntar medio" / "Agregar archivo")
  const pideMedio = m => /adjuntar medio|agregar archivo/i.test((m && m.innerText) || '');

  function zonaAdjuntar(modal) {
    const cands = [...modal.querySelectorAll('button, [role="button"], label, div, span, p')].filter(el => {
      if (el.closest(PANEL_ID)) return false;
      const t = textoDe(el);
      if (!/^(agregar|subir|seleccionar|elegir) archivo/i.test(t) || t.length > 30) return false;
      const r = el.getBoundingClientRect();
      return r.width > 0 && r.height > 0;
    });
    if (!cands.length) return null;
    const hoja = cands.find(c => !cands.some(o => o !== c && c.contains(o))) || cands[0];
    const cont = hoja.closest('button, [role="button"], label');
    return cont && modal.contains(cont) && textoDe(cont).length < 40 ? cont : hoja;
  }

  const contarMedios = m => m.querySelectorAll('img[src^="blob:"], img[src^="data:"], video').length;
  function hayAdjunto(modal, file, textoAntes, mediosAntes = 0) {
    const m = modalPlantilla() || modal;
    if (contarMedios(m) > mediosAntes) return true;
    const t = m.innerText || '';
    if (file && t.includes(file.name) && !(textoAntes || '').includes(file.name)) return true;
    if (textoAntes && /agregar archivo/i.test(textoAntes) && !/agregar archivo/i.test(t)) return true;
    return false;
  }

  // Tres vías, de la más limpia a la más forzada:
  //  1) input[type=file] ya presente en el modal
  //  2) clic en "Agregar archivo" interceptando el selector del sistema
  //  3) soltar el archivo (drag & drop) sobre la zona
  async function adjuntarImagen(modal) {
    const file = archivoImagen();
    const antes = modal.innerText || '';
    const mediosAntes = contarMedios(modal);
    const esperar = async (ms) => {
      for (let i = 0; i < ms / 250; i++) { await sleep(250); if (hayAdjunto(modal, file, antes, mediosAntes)) return true; }
      return false;
    };

    // 1)
    const inputs = [...modal.querySelectorAll('input[type="file"]'),
                    ...document.querySelectorAll('[role="dialog"] input[type="file"]')]
      .filter(i => !i.closest(PANEL_ID));
    if (inputs.length) {
      meterArchivo(inputs[0], file);
      if (await esperar(3000)) { log(`🖼 Imagen adjuntada (${file.name})`, 'success'); return true; }
    }

    const zona = zonaAdjuntar(modal);
    if (!zona) { log('❌ No encontré el campo "Adjuntar medio"', 'error'); return false; }

    // 2)
    const proto = WIN.HTMLInputElement.prototype;
    const original = proto.click;
    let capturado = false;
    const falso = function () {
      if (this.type === 'file') {
        capturado = true;
        const inp = this;
        setTimeout(() => meterArchivo(inp, file), 60);
        return;
      }
      return original.apply(this, arguments);
    };
    try {
      proto.click = (typeof exportFunction === 'function') ? exportFunction(falso, WIN) : falso;
      clickUnico(zona);
      await sleep(400);
      const tras = [...modal.querySelectorAll('input[type="file"]')].filter(i => !i.closest(PANEL_ID));
      if (!capturado && tras.length) meterArchivo(tras[0], file);
    } finally {
      await sleep(300);
      proto.click = original;
    }
    if (await esperar(3500)) { log(`🖼 Imagen adjuntada (${file.name})`, 'success'); return true; }

    // 3)
    try {
      const DT = WIN.DataTransfer || DataTransfer;
      const dt = new DT(); dt.items.add(file);
      for (const tipo of ['dragenter', 'dragover', 'drop']) {
        zona.dispatchEvent(new DragEvent(tipo, { bubbles: true, cancelable: true, dataTransfer: dt }));
        await sleep(120);
      }
    } catch (_) {}
    if (await esperar(3000)) { log(`🖼 Imagen adjuntada (${file.name})`, 'success'); return true; }

    log('❌ La imagen no se pudo adjuntar en "Adjuntar medio"', 'error');
    return false;
  }

  // {{1}} nombre · {{2}} cupo · {{3}} cédula
  function variablesDe(item) {
    return { 1: primerNombre(item.nombre) || item.nombre || '.', 2: item.cupo || '.', 3: item.cedula || '.' };
  }
  async function enviarPlantilla(item, enviarDeVerdad) {
    const nombre = CFG.PLANTILLA, nVars = CFG.N_VARS;
    if (!await abrirModalPlantilla()) return { ok: false, motivo: 'No abrió el modal de plantilla' };
    await sleep(900);
    if (!await elegirPlantilla(nombre)) return { ok: false, motivo: `No se eligió "${nombre}"` };
    await sleep(700);
    const modal = modalPlantilla();
    if (!modal) { log('❌ Se perdió el modal de plantilla', 'error'); return { ok: false, motivo: 'Se perdió el modal' }; }
    const inputs = inputsPlantilla(modal, nVars);
    if (Object.keys(inputs).length < nVars) {
      log(`❌ Solo detecté ${Object.keys(inputs).length}/${nVars} campos de "${nombre}"`, 'error');
      return { ok: false, motivo: 'Faltan campos de variables' };
    }
    const val = variablesDe(item);
    for (let n = 1; n <= nVars; n++) { inputs[n].focus(); await sleep(100); setVal(inputs[n], val[n]); await sleep(150); }
    log(`📝 ${nombre}: ${Array.from({ length: nVars }, (_, i) => `{{${i + 1}}}=${val[i + 1]}`).join(' · ')}`, 'info');
    await sleep(400);

    // ── Imagen (también en ensayo, para verificar que entra) ──
    if (CFG.CON_IMAGEN) {
      if (!pideMedio(modal)) {
        log(`❌ "${nombre}" no muestra el campo "Adjuntar medio": la plantilla no tiene encabezado de imagen. No se envía.`, 'error');
        cerrarModalPlantilla(modal); await sleep(600);
        return { ok: false, motivo: 'Plantilla sin campo de imagen' };
      }
      if (!await adjuntarImagen(modal)) {
        cerrarModalPlantilla(modalPlantilla() || modal); await sleep(600);
        return { ok: false, motivo: 'No se adjuntó la imagen' };
      }
    }

    // Espera a que "Enviar" se habilite (la imagen puede tardar en subir)
    let enviar = null;
    for (let i = 0; i < 40 && !enviar; i++) {
      const m = modalPlantilla() || modal;
      enviar = [...(m.parentElement || m).querySelectorAll('button, [role="button"]')]
        .find(b => !b.closest(PANEL_ID) && textoDe(b).toLowerCase() === 'enviar' && !b.disabled);
      if (!enviar) await sleep(250);
    }

    if (!enviarDeVerdad) {
      log(enviar
        ? '🧪 Ensayo: plantilla e imagen listas, "Enviar" habilitado. NO se envía; cierro el modal.'
        : '⚠ Ensayo: el botón "Enviar" no se habilitó (¿falta la imagen o una variable?). Cierro el modal.',
        enviar ? 'info' : 'warn');
      await sleep(700);
      cerrarModalPlantilla(modalPlantilla() || modal);
      await sleep(600);
      return enviar ? { ok: true } : { ok: false, motivo: '"Enviar" no se habilitó' };
    }

    if (!enviar) { log('❌ Botón "Enviar" no disponible (¿falta la imagen o una variable?)', 'error'); return { ok: false, motivo: '"Enviar" no disponible' }; }
    enviar.click();
    try { enviar.disabled = true; } catch (_) {}
    for (let i = 0; i < 20; i++) { await sleep(300); if (!modalPlantilla()) return { ok: true }; }
    log('⚠ El modal de plantilla no se cerró tras enviar', 'warn');
    return { ok: false, motivo: 'La plantilla no confirmó' };
  }

  // ── Procesar un cliente ──────────────────────────────────────────────────
  async function procesarUno(item) {
    const sim = GM_getValue(K_SIM, CFG.SIMULACION);
    // 1) buscar el número en la lista y abrir el chat si ya existe
    let abierto = await abrirChatExistente(item);
    // 2) si no existe, crearlo como contacto nuevo (flujo del botón +)
    if (!abierto) {
      if (!await crearChat(item)) return { ok: false, motivo: 'No se pudo abrir/crear el chat' };
    }
    // 3) enviar (o solo llenar, en ensayo) la plantilla + imagen en el chat abierto
    const r = await enviarPlantilla(item, !sim);
    if (!r.ok) return { ok: false, motivo: r.motivo };
    return { ok: true, sim };
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // BUCLE + TEMPORIZADOR
  // ═══════════════════════════════════════════════════════════════════════════
  let corriendo = false, runStart = 0, enviadosRun = 0, tickTimer = null;

  function pausaSeg() {
    const a = Math.max(0, +GM_getValue(K_P1, CFG.PAUSA_MIN) || 0);
    const b = Math.max(a, +GM_getValue(K_P2, CFG.PAUSA_MAX) || a);
    return a + Math.random() * (b - a);
  }
  function segPorMsgAprox() {
    const a = +GM_getValue(K_P1, CFG.PAUSA_MIN) || 0;
    const b = +GM_getValue(K_P2, CFG.PAUSA_MAX) || 0;
    // el ensayo también recorre toda la UI, así que usa el mismo overhead
    return CFG.SEG_UI_APROX + (a + b) / 2;
  }

  function pintarProgreso() {
    const c = getCola();
    const total = c.length;
    const enviados = c.filter(x => x.estado === 'enviado' || x.estado === 'simulado').length;
    const pend = c.filter(x => x.estado === 'pendiente').length;
    const err = c.filter(x => x.estado === 'error').length;
    const barra = document.getElementById('kr-prog');
    const pct = total ? Math.round(enviados / total * 100) : 0;

    let eta;
    if (corriendo && enviadosRun > 0) {
      const rate = (Date.now() - runStart) / 1000 / enviadosRun; // seg reales por msg
      eta = fmtDur(pend * rate);
    } else {
      eta = fmtDur(pend * segPorMsgAprox());
    }
    if (barra) barra.innerHTML =
      `<b>${enviados}</b>/${total} (${pct}%) · <span style="color:#fbbf24">${pend} pend.</span>` +
      (err ? ` · <span style="color:#f87171">${err} error</span>` : '') +
      `<br><span style="color:#93c5fd">⏱ ${corriendo ? 'restante ~' : 'estimado ~'}${eta}</span>` +
      (corriendo ? ` · en esta tanda: ${enviadosRun}` : '');
    const b2 = document.getElementById('kr-cola');
    if (b2) b2.textContent = total ? `${total} en cola` : 'Cola vacía';
  }

  async function despachar() {
    if (corriendo) return;
    const sim = GM_getValue(K_SIM, CFG.SIMULACION);
    const tope = Math.max(1, +GM_getValue(K_TOPE, CFG.MAX_POR_TANDA) || CFG.MAX_POR_TANDA);
    const pend0 = getCola().filter(x => x.estado === 'pendiente').length;
    if (!pend0) { log('No hay pendientes en la cola.', 'warn'); return; }

    if (!sim && !confirm(
        `MODO REAL — se enviará "${CFG.PLANTILLA}"${CFG.CON_IMAGEN ? ' con imagen' : ''} de verdad.\n\n` +
        `Imagen: ${nombreImagen()}\nPendientes: ${pend0}\nTope en esta tanda: ${tope}\n\n¿Continuar?`)) return;

    corriendo = true; detener = false; runStart = Date.now(); enviadosRun = 0;
    clearInterval(tickTimer); tickTimer = setInterval(pintarProgreso, 1000);
    log(sim ? '🧪 Ensayo iniciado — hace todo menos enviar' : '🚨 Envío REAL iniciado', sim ? 'info' : 'warn');

    let hechos = 0;
    while (!detener && hechos < tope) {
      const cola = getCola();
      const item = cola.find(x => x.estado === 'pendiente');
      if (!item) { log('✅ No quedan pendientes.', 'success'); break; }

      const r = await procesarUno(item);
      if (r.ok) {
        actualizar(item.cedula, { estado: r.sim ? 'simulado' : 'enviado', motivo: r.sim ? 'Simulado' : 'Enviado', ts: Date.now() });
        enviadosRun++; hechos++;
        log(`${r.sim ? '🧪' : '📨'} ${item.nombre || item.telefono} — ${r.sim ? 'simulado' : 'enviado'} (${hechos}/${tope})`, 'success');
      } else {
        actualizar(item.cedula, { estado: 'error', motivo: r.motivo || 'Error', ts: Date.now() });
        log(`❌ ${item.nombre || item.telefono} — ${r.motivo}`, 'error');
      }
      pintarProgreso();
      if (detener) break;

      const quedan = getCola().filter(x => x.estado === 'pendiente').length;
      if (quedan && hechos < tope) {
        const p = pausaSeg();
        log(`⏳ Pausa ${p.toFixed(1)} s…`, 'info');
        await sleep(p * 1000);
      }
    }

    corriendo = false; clearInterval(tickTimer);
    pintarProgreso();
    log(detener ? '■ Detenido por el usuario.' : (hechos >= tope ? `⏸ Tope de tanda alcanzado (${tope}).` : '✅ Tanda terminada.'),
        detener ? 'warn' : 'success');
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // PANEL
  // ═══════════════════════════════════════════════════════════════════════════
  function construirPanel() {
    if (document.getElementById('kr-panel')) return;
    GM_addStyle(`
      #kr-panel{position:fixed;top:70px;right:16px;z-index:999999;width:330px;
        background:#0b1220;border:1px solid #1e3a5f;border-radius:12px;color:#dbeafe;
        font:13px/1.4 -apple-system,Segoe UI,Roboto,sans-serif;box-shadow:0 12px 40px rgba(0,0,0,.5);
        display:flex;flex-direction:column;max-height:86vh}
      #kr-hdr{background:linear-gradient(120deg,#1b4de4,#12318f);padding:10px 12px;border-radius:12px 12px 0 0;
        display:flex;justify-content:space-between;align-items:center;cursor:move;font-weight:700;color:#fff}
      #kr-hdr button{background:none;border:none;color:#fff;cursor:pointer;font-size:15px}
      #kr-body{padding:12px;overflow:auto;display:flex;flex-direction:column;gap:9px}
      #kr-body label{font-size:11px;color:#93c5fd;font-weight:600}
      #kr-body textarea,#kr-body input{width:100%;box-sizing:border-box;background:#060b14;border:1px solid #1e3a5f;
        border-radius:7px;color:#e7ebf0;padding:7px 9px;font:12px monospace}
      #kr-paste{height:88px;resize:vertical;white-space:pre}
      .kr-row{display:flex;gap:8px}.kr-row>*{flex:1}
      #kr-modo{display:flex;align-items:center;gap:7px;background:#0f2417;border:1px solid #16532c;border-radius:7px;padding:7px 9px}
      #kr-modo.real{background:#2a1414;border-color:#7f1d1d}
      #kr-modo input{width:auto}
      .kr-btn{border:none;border-radius:8px;padding:9px;font-weight:700;cursor:pointer;font-size:13px}
      .kr-go{background:#16a34a;color:#fff}.kr-stop{background:#dc2626;color:#fff}
      .kr-load{background:#1b4de4;color:#fff;width:100%}
      .kr-min{background:#1e3a5f;color:#93c5fd}
      #kr-img-box{display:flex;gap:8px;align-items:center;background:#060b14;border:1px solid #1e3a5f;border-radius:7px;padding:6px}
      #kr-img-prev{width:104px;height:52px;object-fit:cover;border-radius:4px;border:1px solid #1e3a5f;background:#fff;cursor:zoom-in;flex-shrink:0}
      #kr-img-box .kr-img-inf{flex:1;display:flex;flex-direction:column;gap:5px;min-width:0}
      #kr-img-nom{font-size:10px;color:#64748b;font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
      .kr-mini{border:none;border-radius:5px;padding:4px 7px;font-size:11px;font-weight:600;cursor:pointer;background:#1e3a5f;color:#93c5fd}
      #kr-zoom{position:fixed;inset:0;z-index:1000000;background:rgba(5,10,25,.85);display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out}
      #kr-zoom img{max-width:100%;max-height:100%;border-radius:10px}
      #kr-prog{background:#060b14;border:1px solid #1e3a5f;border-radius:7px;padding:8px 10px;font-size:12px;line-height:1.6}
      #kr-cola{font-size:11px;color:#64748b}
      #kr-log{max-height:150px;overflow:auto;background:#060b14;border-radius:7px;padding:6px;font-size:11px;line-height:1.5}
      #kr-log .info{color:#7dd3fc}#kr-log .success{color:#86efac}#kr-log .warn{color:#fde68a}#kr-log .error{color:#fca5a5}
    `);
    const p = document.createElement('div');
    p.id = 'kr-panel';
    p.innerHTML = `
      <div id="kr-hdr"><span>📨 KISSU · Recordatorio</span><button id="kr-minbtn">─</button></div>
      <div id="kr-body">
        <label>Pega la lista (cédula, nombre, celular, cupo):</label>
        <textarea id="kr-paste" placeholder="1500787971  JOSE LUIS GARCIA ZAMORA  0989007918  $1150.00"></textarea>
        <button id="kr-cargar" class="kr-btn kr-load">➕ Cargar a la cola</button>

        <label>🖼 Imagen que va con la plantilla:</label>
        <div id="kr-img-box">
          <img id="kr-img-prev" alt="" title="Clic para ver en grande">
          <div class="kr-img-inf">
            <span id="kr-img-nom"></span>
            <div style="display:flex;gap:5px">
              <button id="kr-img-cambiar" class="kr-mini">Cambiar</button>
              <button id="kr-img-orig" class="kr-mini" style="background:#312e81;color:#c7d2fe">Original</button>
            </div>
          </div>
          <input type="file" id="kr-img-file" accept="image/png,image/jpeg" style="display:none">
        </div>

        <div id="kr-modo">
          <input type="checkbox" id="kr-sim" checked>
          <label for="kr-sim" id="kr-sim-lbl" style="cursor:pointer;margin:0">🧪 Ensayo (hace todo, NO envía)</label>
        </div>

        <div class="kr-row">
          <div><label>Pausa mín (s)</label><input type="number" id="kr-p1" min="0" step="1"></div>
          <div><label>Pausa máx (s)</label><input type="number" id="kr-p2" min="0" step="1"></div>
          <div><label>Tope tanda</label><input type="number" id="kr-tope" min="1" step="1"></div>
        </div>

        <div id="kr-prog">Cola vacía</div>
        <div class="kr-row">
          <button id="kr-go" class="kr-btn kr-go">▶ Procesar</button>
          <button id="kr-stop" class="kr-btn kr-stop">■ Detener</button>
        </div>
        <div class="kr-row">
          <button id="kr-reset" class="kr-btn kr-min">↺ Reintentar errores</button>
          <button id="kr-clear" class="kr-btn kr-min">🗑 Vaciar cola</button>
        </div>
        <div id="kr-cola">Cola vacía</div>
        <label>Log:</label>
        <div id="kr-log"></div>
      </div>`;
    document.body.appendChild(p);

    // estado inicial de controles
    const sim = document.getElementById('kr-sim');
    sim.checked = GM_getValue(K_SIM, CFG.SIMULACION);
    const pintarModo = () => {
      document.getElementById('kr-modo').classList.toggle('real', !sim.checked);
      document.getElementById('kr-sim-lbl').textContent = sim.checked ? '🧪 Ensayo (hace todo, NO envía)' : '🚨 MODO REAL — envía de verdad';
    };
    sim.onchange = () => {
      if (!sim.checked && !confirm('Vas a activar el MODO REAL.\nLos mensajes se enviarán de verdad.\n\n¿Confirmas?')) sim.checked = true;
      GM_setValue(K_SIM, sim.checked); pintarModo(); pintarProgreso();
    };
    pintarModo();

    // Imagen
    const pintarImagen = () => {
      document.getElementById('kr-img-prev').src = imagenActual();
      document.getElementById('kr-img-nom').textContent = nombreImagen() +
        (GM_getValue(K_IMG, '') ? '' : ' (original)');
    };
    pintarImagen();
    const fImg = document.getElementById('kr-img-file');
    document.getElementById('kr-img-cambiar').onclick = () => fImg.click();
    fImg.onchange = () => {
      const f = fImg.files && fImg.files[0];
      if (!f) return;
      if (!/^image\/(png|jpe?g)$/.test(f.type)) { log('⚠ Usa una imagen PNG o JPG', 'warn'); return; }
      if (f.size > 5 * 1024 * 1024) { log('⚠ La imagen pasa de 5 MB, WhatsApp no la acepta', 'warn'); return; }
      const rd = new FileReader();
      rd.onload = () => {
        GM_setValue(K_IMG, rd.result);
        GM_setValue(K_IMG_NOMBRE, f.name);
        pintarImagen();
        log(`🖼 Imagen cambiada: ${f.name}`, 'success');
      };
      rd.readAsDataURL(f);
      fImg.value = '';
    };
    document.getElementById('kr-img-orig').onclick = () => {
      GM_setValue(K_IMG, ''); GM_setValue(K_IMG_NOMBRE, '');
      pintarImagen();
      log('🖼 Imagen original restaurada', 'info');
    };
    document.getElementById('kr-img-prev').onclick = () => {
      const z = document.createElement('div');
      z.id = 'kr-zoom';
      z.innerHTML = `<img src="${imagenActual()}" alt="">`;
      z.onclick = () => z.remove();
      document.body.appendChild(z);
    };

    const p1 = document.getElementById('kr-p1'), p2 = document.getElementById('kr-p2'), tope = document.getElementById('kr-tope');
    p1.value = GM_getValue(K_P1, CFG.PAUSA_MIN);
    p2.value = GM_getValue(K_P2, CFG.PAUSA_MAX);
    tope.value = GM_getValue(K_TOPE, CFG.MAX_POR_TANDA);
    p1.onchange = () => { GM_setValue(K_P1, Math.max(0, +p1.value || 0)); pintarProgreso(); };
    p2.onchange = () => { GM_setValue(K_P2, Math.max(0, +p2.value || 0)); pintarProgreso(); };
    tope.onchange = () => { GM_setValue(K_TOPE, Math.max(1, +tope.value || 1)); };

    document.getElementById('kr-cargar').onclick = () => {
      const ta = document.getElementById('kr-paste');
      const { add, dup, total } = cargarLista(ta.value);
      log(`📥 ${add} agregados${dup ? `, ${dup} ya estaban` : ''}. Total en cola: ${total}.`, 'success');
      ta.value = '';
      pintarProgreso();
    };
    document.getElementById('kr-go').onclick = despachar;
    document.getElementById('kr-stop').onclick = () => { detener = true; log('■ Deteniendo…', 'warn'); };
    document.getElementById('kr-reset').onclick = () => {
      const c = getCola(); let n = 0;
      c.forEach(x => { if (x.estado === 'error') { x.estado = 'pendiente'; x.motivo = ''; n++; } });
      setCola(c); pintarProgreso(); log(`↺ ${n} errores devueltos a pendiente`, 'info');
    };
    document.getElementById('kr-clear').onclick = () => {
      const c = getCola();
      const ya = c.filter(x => x.estado === 'enviado' || x.estado === 'simulado').length;
      if (!confirm(`Vaciar la cola completa (${c.length}).${ya ? `\n\n⚠ ${ya} ya estaban marcados como enviados/simulados.` : ''}\n\n¿Continuar?`)) return;
      setCola([]); pintarProgreso(); log('🗑 Cola vaciada', 'warn');
    };
    document.getElementById('kr-minbtn').onclick = () => {
      const b = document.getElementById('kr-body');
      b.style.display = b.style.display === 'none' ? 'flex' : 'none';
    };

    // arrastrar el panel
    let dx, dy, drag = false;
    document.getElementById('kr-hdr').addEventListener('mousedown', e => {
      if (e.target.tagName === 'BUTTON') return;
      drag = true; dx = e.clientX - p.offsetLeft; dy = e.clientY - p.offsetTop;
    });
    document.addEventListener('mousemove', e => { if (drag) { p.style.left = (e.clientX - dx) + 'px'; p.style.right = 'auto'; p.style.top = (e.clientY - dy) + 'px'; } });
    document.addEventListener('mouseup', () => drag = false);

    GM_addValueChangeListener(K_COLA, () => pintarProgreso());
    pintarProgreso();
    log(`Panel listo. Imagen: ${nombreImagen()}. Pega la lista, carga a la cola y presiona Procesar (empieza en modo Ensayo: hace todo menos enviar).`, 'success');
  }

  // Esperar a que WhaTicket cargue y montar el panel
  const t = setInterval(() => {
    if (document.readyState === 'complete' && document.body) {
      clearInterval(t);
      setTimeout(construirPanel, 1800);
    }
  }, 500);

})();
